        CultEvent.Random("ac04", StatId.Doctrine, new Question("측근들이 '지도자와의 합일은 축복'이라는 교리를 만들자고 제안합니다. 그렇게 쓰이는 순간, 신도들은 거절을 죄로 여기게 될 것입니다.\u001FYour inner circle proposes a Doctrine: 'Union with the leader is a blessing.' The moment it's written, followers will see refusal as a sin.",
                new Choice("교리로 승인한다\u001FApprove it as Doctrine", 0.55f, new Outcome("교리는 문서가 되었고, 신도들은 그것을 외웁니다. 이제 아무도 거절하지 않습니다. 그것이 믿음인지 두려움인지, 당신은 묻지 않기로 합니다.\u001FThe Doctrine is put in writing, and the followers memorize it. Now no one refuses. Whether that's faith or fear, you decide not to ask.").P(PersonalStatId.Lust, 3).P(PersonalStatId.Integrity, -10).C(StatId.Doctrine, 8).C(StatId.Authority, 6),
                    new Outcome("초안이 외부로 새어 나갑니다. 방송사가 탈퇴자 인터뷰를 내보내고, 교단은 '성착취 사이비'로 불리기 시작합니다.\u001FThe draft leaks. A broadcaster airs interviews with ex-members, and the cult starts being called 'a sex-exploitation cult.'").P(PersonalStatId.Integrity, -10).C(StatId.Reputation, -30).C(StatId.Followers, -12)).With(PersonalStatId.Lust),
