                    new Outcome("황제는 만족하지 못했습니다. 궁정에 '가짜 신' 이야기가 돕니다.\u001FThe emperor was not satisfied. Talk of a 'false god' spreads through the court.").P(PersonalStatId.Lust, 2).C(StatId.Authority, -6).X(GodEventEffect.Suspicion, 5)).With(PersonalStatId.Lust),
