        CultEvent.Random("xg07", StatId.Offerings, new Question("황금의 신이 당신 신전의 빈 금고를 보고 비웃습니다. \"하룻밤이면 저 금고를 채워 주지. 대가는 네 그릇이다. 하룻밤만.\"\u001FThe god of gold sneers at your temple's empty treasury. \"I could fill that vault in a single night. The price is your vessel. Just for one night.\"",
                new Choice("하룻밤 그릇을 빌려준다\u001FLend him your vessel for one night", 0.65f, new Outcome("그의 손길이 닿는 곳마다 금가루가 반짝입니다. 사치스럽고 탐욕스러운 밤이 지나자 금고에서 금화가 넘쳐 흐릅니다.\u001FGold dust glitters wherever his hands touch. After a lavish, greedy night, gold coins overflow from the vault.").P(PersonalStatId.Lust, 3).C(StatId.Offerings, 15),
