                new Choice("천사를 천계로 돌려보낸다\u001FSend the angel back to heaven", new Outcome("그녀는 눈물을 흘리며 날아오릅니다. 그녀의 보고는 당신에게 유리하게 쓰입니다.\u001FShe flies off in tears. Her report is written in your favor.").P(PersonalStatId.Integrity, 3).X(GodEventEffect.Envy, -3)))),
        CultEvent.Random("xg11", StatId.Followers, new Question("이웃 마을의 다산 축제에 초대받았습니다. 마을 사람들은 신이 축제의 첫 춤을 추면 풍년이 든다고 믿습니다. 축제의 꽃인 30대 과부가 당신에게 화관을 씌웁니다.\u001FYou're invited to a fertility festival in a neighboring village. The villagers believe that if a god dances the festival's first dance, the harvest will be bountiful. The festival's beauty, a widow in her thirties, places a garland on your head.",
