        CultEvent.Random("xg18", StatId.Reputation, new Question("거울의 신이 당신 그릇과 똑같은 모습으로 나타났습니다. \"자신을 안아 본 신은 드물지. 궁금하지 않아?\"\u001FThe god of mirrors appears in a form identical to your vessel. \"Few gods have ever held themselves. Aren't you curious?\"",
