                new Choice("명계의 왕을 녹여 준다\u001FMelt the king of the underworld", 0.60f, new Outcome("얼음 같은 몸이 당신 체온에 조금씩 풀립니다. 그가 처음으로 붉게 달아오른 얼굴로 숨을 몰아쉴 때, 명계의 문이 당신 신도들에게 조금 너그러워집니다.\u001FHis icy body thaws bit by bit against your warmth. When he gasps for breath, his face flushed for the first time, the gates of the underworld grow a little more lenient toward your followers.").P(PersonalStatId.Lust, 4).C(StatId.Authority, 8).X(GodEventEffect.Points, 2),
                    new Outcome("냉기가 그릇 깊숙이 스며들었습니다. 그리고 천계는 명계와 엮인 당신을 곱게 보지 않습니다.\u001FThe chill has seeped deep into your vessel. And heaven doesn't look kindly on your ties to the underworld.").P(PersonalStatId.Lust, 2).P(PersonalStatId.Health, -5).X(GodEventEffect.Envy, 4)).With(PersonalStatId.Lust),
                new Choice("따뜻한 차를 대접한다\u001FServe him warm tea", new Outcome("그는 차 한 잔에 의외로 감동합니다. \"다음엔 내가 대접하지.\"\u001FHe's surprisingly moved by a single cup of tea. \"Next time, I'll be the host.\"").P(PersonalStatId.Charity, 3).C(StatId.Authority, 3)))),
        CultEvent.Random("xg30", StatId.LeaderFaith, new Question("신이 된 뒤 처음 맞는 기념일, 천계의 오랜 연인(어느 신인지는 당신만 압니다)이 몰래 찾아옵니다. \"지상에 내려가더니 날 잊은 줄 알았어. 그 몸으로 나를 다시 기억해 줘.\"\u001FOn your first anniversary as a god, an old lover from heaven (only you know which god) visits in secret. \"I thought you'd forgotten me once you went down to the mortal world. Remember me again with that body.\"",
                new Choice("옛 연인을 그릇으로 맞이한다\u001FWelcome your old lover in your vessel", 0.75f, new Outcome("천계에서 나누던 사랑이 처음으로 살과 피를 얻습니다. 익숙한 영혼과 낯선 육체 사이에서 두 사람은 밤새 서로를 다시 배웁니다. 새벽, 당신은 왜 신이 되었는지 기억해 냅니다.\u001FThe love you shared in heaven takes on flesh and blood for the first time. Between a familiar soul and an unfamiliar body, the two of you relearn each other all night. At dawn, you remember why you became a god.").P(PersonalStatId.Lust, 4).C(StatId.LeaderFaith, 8),
                    new Outcome("천계에 두 사람의 밀회가 들통났습니다. 연인을 시기하던 신들이 당신을 노립니다.\u001FYour tryst is exposed in heaven. The gods who envied your lover set their sights on you.").P(PersonalStatId.Lust, 2).X(GodEventEffect.Envy, 6)).With(PersonalStatId.Lust),
                new Choice("천계에서 다시 만나자고 약속한다\u001FPromise to meet again in heaven", new Outcome("연인은 눈물을 훔치며 웃습니다. \"승천하면 그때 실컷.\"\u001FYour lover wipes away tears and smiles. \"Once you ascend, then we'll have all the time we want.\"").P(PersonalStatId.Patience, 3).C(StatId.LeaderFaith, 3)))),
