    // 이 모드에서 뽑을 수 있는 성인 이벤트 (반복 등장하는 확률 이벤트)
    public static readonly CultEvent[] Normal = Shared.Concat(NormalOnly).ToArray();
    public static readonly CultEvent[] God = Shared.Concat(GodOnly).ToArray();
    public static readonly CultEvent[] All = Shared.Concat(NormalOnly).Concat(GodOnly).ToArray();

    // 플레이어 성별 전용 이벤트 (adult_events.csv의 player 열). 상대 성별이 바뀐 변형은 id 끝에 _m/_f를 붙인다.
    static readonly System.Collections.Generic.HashSet<string> MaleOnly = new() { "ad01", "ad02_m", "ad03", "ad05_m", "ad07_m", "ad08", "xn01", "xn03_m", "xn04", "xn05", "xn06_m", "xn10", "xn11_m", "xn12", "xn13", "xn16", "xn17_m", "xn19", "xn20_m", "xn21", "xn22_m", "xn23", "xn24", "xn25_m", "xn26", "xn27_m", "xn28", "xg01", "xg02", "xg06", "xg08_m", "xg09", "xg10_m", "xg11", "xg12", "xg13_m", "xg15", "xg16", "xg19_m", "xg21", "xg22_m", "xg23_m", "xg24", "xg25", "xg26_m", "xg27_m", "xg28_m", "xg29" };
    static readonly System.Collections.Generic.HashSet<string> FemaleOnly = new() { "ad01_f", "ad02", "ad03_f", "ad05", "ad07", "ad08_f", "xn01_f", "xn03", "xn04_f", "xn05_f", "xn06", "xn10_f", "xn11", "xn12_f", "xn13_f", "xn16_f", "xn17", "xn19_f", "xn20", "xn21_f", "xn22", "xn23_f", "xn24_f", "xn25", "xn26_f", "xn27", "xn28_f", "xg01_f", "xg02_f", "xg06_f", "xg08", "xg09_f", "xg10", "xg11_f", "xg12_f", "xg13", "xg15_f", "xg16_f", "xg19", "xg21_f", "xg22", "xg23", "xg24_f", "xg25_f", "xg26", "xg27", "xg28", "xg29_f" };

    public static bool Fits(CultEvent e, Gender gender) =>
        gender == Gender.Male ? !FemaleOnly.Contains(e.Id) : !MaleOnly.Contains(e.Id);

    public static CultEvent[] Pool(bool godMode) =>
        (godMode ? God : Normal).Where(e => GameSession.Personal == null || Fits(e, GameSession.Personal.Gender)).ToArray();
}
